termList = []
wordList = []
phraseList = []
excludeList = []
const OPERATORS = {from: 'from', to: 'to', cc: 'cc', bcc: 'bcc', subject: 'subject', has: 'has', label: 'label', in: 'in',
    is: 'is', before: 'before', after: 'after', older_than: 'older_than', newer_than: 'newer_than', larger: 'larger',
    smaller: 'smaller', size: 'larger', filename: 'filename'}
const HAS = ['attachment', 'attachments']
const IS = ['unread', 'read', 'flagged', 'starred', 'answered', 'snoozed']
const source = String(searchText || '')
const space = (ch) => /\s/.test(ch)
const shown = []
let index = 0
// a value up to its closing quote or parenthesis, or the next space
const readValue = () => {
    const open = source[index]
    const close = open === '"' ? '"' : (open === '(' ? ')' : null)
    if (close) {
        const end = source.indexOf(close, index + 1)
        const value = end < 0 ? source.substring(index + 1) : source.substring(index + 1, end)
        index = end < 0 ? source.length : end + 1
        return value.trim()
    }
    const start = index
    while (index < source.length && !space(source[index])) index++
    return source.substring(start, index)
}
while (index < source.length) {
    while (index < source.length && space(source[index])) index++
    if (index >= source.length) break
    const tokenStart = index
    let negate = false
    if (source[index] === '-' && index + 1 < source.length && !space(source[index + 1])) { negate = true; index++ }
    if (source[index] === '"') {
        const phrase = readValue()
        if (!phrase) continue
        if (negate) excludeList.push(phrase)
        else phraseList.push(phrase)
        shown.push(source.substring(tokenStart, index))
        continue
    }
    const nameStart = index
    while (index < source.length && !space(source[index]) && source[index] !== ':' && source[index] !== '"') index++
    const name = source.substring(nameStart, index).toLowerCase()
    if (source[index] === ':' && OPERATORS[name] && index + 1 < source.length && !space(source[index + 1])) {
        index++
        const operator = OPERATORS[name]
        const raw = readValue()
        const value = ['has', 'is', 'in'].includes(operator) ? raw.toLowerCase() : raw
        if (!value) continue
        if (operator === 'has' && !HAS.includes(value)) { ec.message.addError(`has:${raw} is not a search term; has:attachment is`); return }
        if (operator === 'is' && !IS.includes(value)) { ec.message.addError(`is:${raw} is not a search term: is:${IS.join(', is:')}`); return }
        termList.push({operator: operator, value: operator === 'has' ? 'attachment' : value, negate: negate})
        continue
    }
    // a word, which may hold a colon (a URL, a time)
    while (index < source.length && !space(source[index])) index++
    const word = source.substring(nameStart, index)
    if (!word) continue
    if (negate) excludeList.push(word)
    else wordList.push(word)
    shown.push(source.substring(tokenStart, index))
}
freeText = shown.join(' ')
hasFreeText = wordList.length > 0 || phraseList.length > 0 || excludeList.length > 0

const cf = ec.entity.conditionFactory
const MESSAGE = 'moqui.basic.email.EmailMessage'
const VIEWS = ['inbox', 'flagged', 'snoozed', 'scheduled', 'outbox', 'drafts', 'sent', 'archive', 'junk', 'trash', 'all', 'anywhere', 'folder', 'label']
const LIST_FIELDS = ['emailMessageId', 'rootEmailMessageId', 'parentEmailMessageId', 'emailAccountId', 'emailFolderId',
    'statusId', 'subject', 'snippet', 'fromAddress', 'fromName', 'toAddresses', 'ccAddresses', 'messageDate', 'isRead',
    'isFlagged', 'isAnswered', 'hasAttachment', 'snoozedThruDate', 'scheduledSendDate', 'archivedDate', 'sendError', 'messageSize']
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const number = Number(value)
    return Number.isNaN(number) ? new Date(String(value)).getTime() : number
}
const splitAddresses = (text) => {
    const out = []
    if (!text) return out
    let current = '', quote = false, angle = 0
    for (const ch of String(text)) {
        if (ch === '"') quote = !quote
        else if (ch === '<' && !quote) angle++
        else if (ch === '>' && !quote && angle > 0) angle--
        else if (ch === ',' && !quote && angle === 0) { if (current.trim()) out.push(current.trim()); current = ''; continue }
        current += ch
    }
    if (current.trim()) out.push(current.trim())
    return out.map((entry) => {
        const match = /^(.*)<([^>]+)>\s*$/.exec(entry)
        if (!match) return {address: entry, name: null}
        const name = match[1].trim().replace(/^"(.*)"$/, '$1').trim()
        return {address: match[2].trim(), name: name || null}
    })
}
threadList = []
hasMore = false
nextBeforeDate = null
termList = []
searchMode = null
// the search line: its operators, and the free text for the index
let search = {termList: [], wordList: [], phraseList: [], excludeList: [], hasFreeText: false}
if (searchText && String(searchText).trim()) {
    search = ec.service.sync().name('org.moqui.impl.EmailClientServices.parse#SearchText').parameter('searchText', searchText).call()
    if (ec.message.hasError()) return
    termList = search.termList || []
}
const terms = (operator) => termList.filter((term) => term.operator === operator)
// in: is the view, or the folders of that name (read once the accounts are known)
const IN_VIEWS = {inbox: 'inbox', sent: 'sent', drafts: 'drafts', draft: 'drafts', scheduled: 'scheduled', outbox: 'outbox',
    snoozed: 'snoozed', flagged: 'flagged', starred: 'flagged', archive: 'archive', archived: 'archive', spam: 'junk', junk: 'junk',
    trash: 'trash', bin: 'trash', all: 'all', allmail: 'all', 'all mail': 'all', anywhere: 'anywhere'}
let inFolderName = null
for (const term of terms('in')) {
    if (term.negate) { ec.message.addError(`-in:${term.value} is not a search term; in: names one view or folder`); return }
    if (IN_VIEWS[term.value]) { view = IN_VIEWS[term.value]; inFolderName = null; emailFolderId = null; emailLabelId = null }
    else { inFolderName = term.value; view = 'folder' }
}
if (!view) view = emailFolderId ? 'folder' : (emailLabelId ? 'label' : 'inbox')
if (!VIEWS.includes(view)) { ec.message.addError(`Unknown view ${view}: ${VIEWS.join(', ')}`); return }
if (view === 'folder' && !emailFolderId && !inFolderName) { ec.message.addError('The folder view needs an emailFolderId'); return }
if (view === 'label' && !emailLabelId) { ec.message.addError('The label view needs an emailLabelId'); return }
if (!(pageSize > 0)) pageSize = 50

const access = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailAccountAccess').call()
if (ec.message.hasError()) return
let accountIds = access.accountList.filter((account) => !account.isInternal).map((account) => account.emailAccountId)
const wanted = [].concat(emailAccountId ? [emailAccountId] : [], emailAccountIdList || [])
if (wanted.length) {
    for (const id of wanted) if (!access.accessMap[id]) { ec.message.addError(`Email account ${id} not found`); return }
    accountIds = accountIds.filter((id) => wanted.includes(id))
}
if (accountIds.length === 0) return

const folderKind = {}
