let viewFolderIds = emailFolderId ? [emailFolderId] : []
if (inFolderName) {
    const wanted = String(inFolderName).toLowerCase()
    viewFolderIds = folderRows.filter((folder) => String(folder.folderName || '').toLowerCase() === wanted ||
            String(folder.folderPath || '').toLowerCase() === wanted).map((folder) => folder.emailFolderId)
    if (!viewFolderIds.length) { ec.message.addError(`No folder ${inFolderName} (in:${inFolderName})`); return }
}
let labeledIds = null
if (view === 'label') {
    const label = ec.entity.find('moqui.basic.email.EmailLabel').condition('emailLabelId', emailLabelId).one()
    if (label == null || !accountIds.includes(label.emailAccountId)) { ec.message.addError(`Email label ${emailLabelId} not found`); return }
    labeledIds = Array.from(ec.entity.find('moqui.basic.email.EmailMessageLabel').condition('emailLabelId', emailLabelId)
            .selectField('emailMessageId').list()).map((row) => row.emailMessageId)
    if (labeledIds.length === 0) return
}
const now = ec.user.nowTimestamp
const nowMillis = toMillis(now)
const trashJunk = byKind.EfkTrash.concat(byKind.EfkJunk)
const inTrashView = view === 'trash' || view === 'junk' || (view === 'folder' && viewFolderIds.every((id) => trashJunk.includes(id)))
const anywhere = view === 'anywhere'
const notSnoozed = () => cf.makeCondition([cf.makeCondition('snoozedThruDate', 'equals', null),
    cf.makeCondition('snoozedThruDate', 'less-equals', now)], 'or')

// the operators of the search line as conditions; false when one cannot match anything
const like = (field, text) => cf.makeCondition(field, 'like', `%${text}%`, false, true)
const notLike = (field, text) => cf.makeCondition(field, 'not-like', `%${text}%`, true, true)
const anyLike = (fields, text, negate) => negate ? cf.makeCondition(fields.map((field) => notLike(field, text)), 'and')
        : cf.makeCondition(fields.map((field) => like(field, text)), 'or')
