    if (!match) return null
    const unit = {'': 1, k: 1024, m: 1048576, g: 1073741824}[match[2].toLowerCase()]
    return Math.round(Number(match[1]) * unit)
}
const termConditions = []
for (const term of termList) {
    const value = String(term.value)
    const negate = term.negate === true
    let condition = null
    switch (term.operator) {
        case 'in': continue
        case 'from': condition = anyLike(['fromAddress', 'fromName'], value, negate); break
        case 'to': condition = anyLike(['toAddresses', 'ccAddresses', 'bccAddresses'], value, negate); break
        case 'cc': condition = anyLike(['ccAddresses'], value, negate); break
        case 'bcc': condition = anyLike(['bccAddresses'], value, negate); break
        case 'subject': condition = anyLike(['subject'], value, negate); break
        case 'has': condition = flagIs('hasAttachment', !negate); break
        case 'is':
            if (value === 'unread') condition = flagIs('isRead', negate)
            else if (value === 'read') condition = flagIs('isRead', !negate)
            else if (value === 'answered') condition = flagIs('isAnswered', !negate)
            else if (value === 'snoozed') condition = negate ? notSnoozed() : cf.makeCondition('snoozedThruDate', 'greater', now)
            else condition = flagIs('isFlagged', !negate)
            break
        case 'label': {
            // a label by its name in any of the accounts, a - matching a space as Gmail writes label:my-label
            const name = (text) => String(text || '').toLowerCase().replace(/[\s_-]+/g, ' ').trim()
            const labelIds = Array.from(ec.entity.find('moqui.basic.email.EmailLabel').condition('emailAccountId', 'in', accountIds)
                    .selectField('emailLabelId').selectField('labelName').list()).filter((label) => name(label.labelName) === name(value))
                    .map((label) => label.emailLabelId)
            const ids = labelIds.length ? Array.from(ec.entity.find('moqui.basic.email.EmailMessageLabel').condition('emailLabelId', 'in', labelIds)
                    .selectField('emailMessageId').list()).map((row) => row.emailMessageId) : []
            condition = idsIn(Array.from(new Set(ids)), negate)
            break
        }
        case 'filename': {
            const ids = Array.from(ec.entity.find('moqui.basic.email.EmailMessageAttachment').condition(like('fileName', value))
                    .selectField('emailMessageId').list()).map((row) => row.emailMessageId)
            condition = idsIn(Array.from(new Set(ids)), negate)
            break
        }
        case 'before': case 'after': {
            const day = dayOf(value)
            if (day == null) { ec.message.addError(`${term.operator}:${value} needs a date, such as ${term.operator}:2026/10/19`); return }
            const before = (term.operator === 'before') !== negate
            condition = cf.makeCondition('messageDate', before ? 'less' : 'greater-equals', day)
            break
        }
        case 'older_than': case 'newer_than': {
            const at = agoOf(value)
            if (at == null) { ec.message.addError(`${term.operator}:${value} needs a count of days, weeks, months or years, such as ${term.operator}:2d`); return }
            const older = (term.operator === 'older_than') !== negate
            condition = cf.makeCondition('messageDate', older ? 'less' : 'greater-equals', at)
            break
        }
        case 'larger': case 'smaller': {
            const bytes = bytesOf(value)
            if (bytes == null) { ec.message.addError(`${term.operator}:${value} needs a size, such as ${term.operator}:5M`); return }
            const larger = (term.operator === 'larger') !== negate
            condition = cf.makeCondition('messageSize', larger ? 'greater-equals' : 'less', bytes)
