// the free text: through the search index when it is there, else in the subject, body and addresses
const beforeMillis = toMillis(beforeDate)
// the index's matches (newest first), and one read of them: the ids matching filters, at most limit
let indexQuery = null
const indexIds = (filters, limit) => Array.from(ec.search.search({documentType: 'MoquiEmailMessage', query: indexQuery,
        filter: {bool: {all: [{field: {name: 'emailAccountId', op: 'in', values: accountIds}}].concat(filters)}},
        sort: ['-messageDate'], limit: limit, consistency: 'readYourWrites', freshTimeout: 2000}).hits).map((hit) => String(hit.id))
// The index's matches in windows of searchLimit, newest first from the page's cursor (beforeDate), so a view
// of any size pages: a full window holds the matches dated after the oldest one it read, and the next window
// reads from that date again. Each window is {ids}; without the index the one window is {ids: null}, the view.
const indexBatch = searchLimit > 0 ? searchLimit : 2000
let windowEnd = beforeMillis
let windowsDone = false
const readIndexWindow = () => {
    const ids = Array.from(new Set(indexIds(windowEnd == null ? [] : [{field: {name: 'messageDate', op: 'range', lt: windowEnd}}], indexBatch)))
    if (ids.length < indexBatch) { windowsDone = true; return {ids: ids} }
    // the dates as stored, so each window ends where the next begins
    const dated = Array.from(ec.entity.find(MESSAGE).condition('emailMessageId', 'in', ids).selectField('emailMessageId')
            .selectField('messageDate').list()).map((row) => ({id: row.emailMessageId, at: toMillis(row.messageDate)}))
            .filter((row) => row.at != null)
    if (!dated.length) {
        ec.logger.warn(`The mail search index matched ${ids.length} messages that are not stored; the search ends there`)
        windowsDone = true
        return {ids: []}
    }
    const floor = Math.min.apply(null, dated.map((row) => row.at))
    const newer = dated.filter((row) => row.at > floor).map((row) => row.id)
    if (!newer.length) {
        // a whole window dated one millisecond: take it, and go on before it
        ec.logger.warn(`The mail search matched more than ${indexBatch} messages dated ${floor}; the ones past those are left out`)
        windowEnd = floor
        return {ids: dated.map((row) => row.id)}
    }
    windowEnd = floor + 1
    return {ids: newer}
}
let firstWindow = null
let viewWindowDone = false
const nextWindow = () => {
    if (indexQuery == null) { if (viewWindowDone) return null; viewWindowDone = true; return {ids: null} }
    if (firstWindow != null) { const window = firstWindow; firstWindow = null; return window }
    if (windowsDone) return null
    try { return readIndexWindow() }
    catch (err) {
        ec.logger.error(`The mail search index failed reading past ${windowEnd}; the list ends there: ${err.message || err}`)
        windowsDone = true
        return null
    }
}
const TEXT_FIELDS = ['subject', 'body', 'bodyText', 'fromAddress', 'fromName', 'toAddresses', 'ccAddresses']
if (search.hasFreeText) {
    const DOCUMENT = 'MoquiEmailMessage'
    let indexed = false
    try { indexed = ec.search.isAvailable() && ec.search.indexExists({documentType: DOCUMENT}) }
    catch (err) { ec.logger.warn(`Could not find the mail search index: ${err.message || err}`) }
    if (indexed) {
        try {
            const FIELDS = ['subject', 'bodyText', 'fromName', 'fromAddress', 'toAddresses', 'ccAddresses', 'labels.labelName']
            const words = search.wordList || []
            // every word in one of the fields, the last one as a prefix (what is being typed)
            const all = words.map((word, position) => ({text: {terms: word, fields: FIELDS, match: position === words.length - 1 ? 'prefix' : 'term'}}))
            for (const phrase of search.phraseList || []) all.push({text: {terms: phrase, fields: FIELDS, match: 'phrase'}})
            const none = (search.excludeList || []).map((text) => ({text: {terms: text, fields: FIELDS, match: /\s/.test(text) ? 'phrase' : 'term'}}))
            indexQuery = {bool: {all: all.length ? all : ['match_all'], none: none}}
            // the first window here, so an index that fails falls back to the text search
            firstWindow = readIndexWindow()
            searchMode = 'index'
        } catch (err) {
            indexQuery = null
            ec.logger.warn(`The mail search index failed, searching the messages instead: ${err.message || err}`)
        }
    }
    if (searchMode == null) {
        searchMode = 'text'
        for (const word of search.wordList || []) termConditions.push(anyLike(TEXT_FIELDS, word, false))
        for (const phrase of search.phraseList || []) termConditions.push(anyLike(TEXT_FIELDS, phrase, false))
        for (const text of search.excludeList || []) termConditions.push(anyLike(TEXT_FIELDS, text, true))
    }
}
const notTrashJunk = () => trashJunk.length ? cf.makeCondition('emailFolderId', 'not-in', trashJunk, true) : null
const inFolders = (ids) => ids.length ? cf.makeCondition('emailFolderId', 'in', ids) : null
// the conditions of the view and the filters; null when the view can have no message
const viewConditions = () => {
    const list = []
    const add = (condition) => { if (condition != null) list.push(condition) }
    switch (view) {
        case 'inbox':
            if (!byKind.EfkInbox.length) return null
            add(inFolders(byKind.EfkInbox)); add(cf.makeCondition('archivedDate', 'equals', null)); add(notSnoozed()); break
        case 'flagged': add(cf.makeCondition('isFlagged', 'equals', 'Y')); add(notTrashJunk()); break
        case 'snoozed': add(cf.makeCondition('snoozedThruDate', 'greater', now)); add(notTrashJunk()); break
        case 'scheduled': add(cf.makeCondition('statusId', 'equals', 'ES_SCHEDULED')); break
        case 'outbox': add(cf.makeCondition('statusId', 'in', ['ES_SCHEDULED', 'ES_READY'])); break
        case 'drafts': add(cf.makeCondition('statusId', 'equals', 'ES_DRAFT')); add(notTrashJunk()); break
        case 'sent': if (!byKind.EfkSent.length) return null; add(inFolders(byKind.EfkSent)); break
        case 'archive': {
            const either = [cf.makeCondition('archivedDate', 'not-equals', null)]
            if (byKind.EfkArchive.length) either.push(inFolders(byKind.EfkArchive))
            add(cf.makeCondition(either, 'or')); add(notTrashJunk()); break
        }
        case 'junk': if (!byKind.EfkJunk.length) return null; add(inFolders(byKind.EfkJunk)); break
        case 'trash': if (!byKind.EfkTrash.length) return null; add(inFolders(byKind.EfkTrash)); break
        case 'all': add(notTrashJunk()); break
        case 'anywhere': break
        case 'folder':
            add(inFolders(viewFolderIds))
            if (viewFolderIds.every((id) => folderKind[id] === 'EfkInbox')) { add(cf.makeCondition('archivedDate', 'equals', null)); add(notSnoozed()) }
            break
        case 'label': add(cf.makeCondition('emailMessageId', 'in', labeledIds)); add(notTrashJunk()); break
    }
    if (unreadOnly) add(cf.makeCondition('isRead', 'not-equals', 'Y', true))
    if (flaggedOnly) add(cf.makeCondition('isFlagged', 'equals', 'Y'))
    if (hasAttachment === true) add(cf.makeCondition('hasAttachment', 'equals', 'Y'))
    if (hasAttachment === false) add(cf.makeCondition('hasAttachment', 'not-equals', 'Y', true))
    if (fromAddress) add(cf.makeCondition([like('fromAddress', fromAddress), like('fromName', fromAddress)], 'or'))
    if (toAddress) add(cf.makeCondition([like('toAddresses', toAddress), like('ccAddresses', toAddress)], 'or'))
    if (subject) add(like('subject', subject))
    if (fromDate != null) add(cf.makeCondition('messageDate', 'greater-equals', fromDate))
    if (thruDate != null) add(cf.makeCondition('messageDate', 'less', thruDate))
    if (minSize != null) add(cf.makeCondition('messageSize', 'greater-equals', minSize))
    if (maxSize != null) add(cf.makeCondition('messageSize', 'less-equals', maxSize))
    for (const condition of termConditions) {
        if (condition === false) return null
        add(condition)
    }
    return list
}
const conditions = viewConditions()
if (conditions == null) return
// the view's messages; with windowIds (an index window), only those
const makeFind = (windowIds) => {
    let find = ec.entity.find(MESSAGE).condition('emailAccountId', 'in', accountIds)
            .condition(cf.makeCondition('messageDate', 'not-equals', null))
    for (const condition of conditions) find = find.condition(condition)
    if (windowIds != null) find = find.condition(cf.makeCondition('emailMessageId', 'in', windowIds))
    return find
}

// the labels of the messages shown
const labelsOf = (messageIds) => {
    const out = {}
    if (!messageIds.length) return out
    const joins = Array.from(ec.entity.find('moqui.basic.email.EmailMessageLabel').condition('emailMessageId', 'in', messageIds).list())
    const labelIds = Array.from(new Set(joins.map((row) => row.emailLabelId)))
    const labels = {}
    if (labelIds.length) for (const label of ec.entity.find('moqui.basic.email.EmailLabel').condition('emailLabelId', 'in', labelIds).list())
        labels[label.emailLabelId] = {emailLabelId: label.emailLabelId, labelName: label.labelName ?? null, color: label.color ?? null}
    for (const row of joins) if (labels[row.emailLabelId]) (out[row.emailMessageId] ||= []).push(labels[row.emailLabelId])
    return out
}
const archiveFolders = new Set(byKind.EfkArchive)
const summarize = (threadId, messages, viewMessageId, sortDate, labelMap) => {
    const first = messages[0]
    const last = messages[messages.length - 1]
    const shown = messages.find((message) => message.emailMessageId === viewMessageId) || last
    const root = messages.find((message) => message.emailMessageId === threadId) || first
    const participants = []
    const seenAddresses = new Set()
    for (const message of messages) {
        for (const entry of [].concat(splitAddresses(message.fromName ? `"${message.fromName}" <${message.fromAddress}>` : message.fromAddress),
                splitAddresses(message.toAddresses), splitAddresses(message.ccAddresses))) {
            const key = String(entry.address).toLowerCase()
            if (!entry.address || seenAddresses.has(key)) continue
            seenAddresses.add(key)
            participants.push(entry)
        }
    }
    const labelList = []
    const labelSeen = new Set()
    for (const message of messages) for (const label of (labelMap[message.emailMessageId] || [])) {
        if (labelSeen.has(label.emailLabelId)) continue
        labelSeen.add(label.emailLabelId)
        labelList.push(label)
    }
    const snoozes = messages.map((message) => toMillis(message.snoozedThruDate)).filter((millis) => millis != null && millis > nowMillis)
    const unreadCount = messages.filter((message) => message.isRead !== 'Y').length
    return {store: 'email', threadId: threadId, rootEmailMessageId: threadId, lastEmailMessageId: last.emailMessageId,
        emailMessageId: shown.emailMessageId, emailAccountId: shown.emailAccountId, emailFolderId: shown.emailFolderId ?? null,
        folderKindEnumId: shown.emailFolderId ? (folderKind[shown.emailFolderId] || null) : null, statusId: shown.statusId ?? null,
        subject: root.subject ?? null, snippet: last.snippet ?? null, sortDate: sortDate,
        lastDate: toMillis(last.messageDate), firstDate: toMillis(first.messageDate),
        messageCount: messages.length, replyCount: messages.length - 1, unreadCount: unreadCount, isUnread: unreadCount > 0,
        isFlagged: messages.some((message) => message.isFlagged === 'Y'),
        isArchived: messages.every((message) => message.archivedDate != null || archiveFolders.has(message.emailFolderId)),
        snoozedThruDate: snoozes.length ? Math.max.apply(null, snoozes) : null,
        scheduledSendDate: toMillis(shown.scheduledSendDate), hasAttachment: messages.some((message) => message.hasAttachment === 'Y'),
        draftCount: messages.filter((message) => message.statusId === 'ES_DRAFT').length,
        fromAddress: last.fromAddress ?? null, fromName: last.fromName ?? null, participantList: participants,
        participantAddressList: participants.map((entry) => entry.address), labelList: labelList, sendError: shown.sendError ?? null,
        fromPartyId: null, participantPartyIdList: [], contactListId: null, contactListName: null, isClosed: false}
}
const plain = (row) => {
    const out = {}
    for (const field of LIST_FIELDS) out[field] = row[field] ?? null
    return out
}
const withCursor = (find) => beforeMillis == null ? find : find.condition(cf.makeCondition('messageDate', 'less', new Date(beforeMillis)))

if (!threadMode) {
    const rows = []
    for (let window = nextWindow(); window != null && rows.length <= pageSize; window = nextWindow()) {
        if (window.ids != null && !window.ids.length) continue
        let find = withCursor(makeFind(window.ids))
        for (const field of LIST_FIELDS) find = find.selectField(field)
        for (const row of find.orderBy('-messageDate').orderBy('-emailMessageId').limit(pageSize + 1 - rows.length).list()) rows.push(plain(row))
    }
    hasMore = rows.length > pageSize
    const page = rows.slice(0, pageSize)
    const labelMap = labelsOf(page.map((row) => row.emailMessageId))
    threadList = page.map((row) => summarize(row.rootEmailMessageId || row.emailMessageId, [row], row.emailMessageId,
            toMillis(row.messageDate), labelMap))
    if (hasMore) nextBeforeDate = threadList[threadList.length - 1].sortDate
    return
}

// threads: scan the view's messages newest first, window by window; a thread comes at its newest one
const chunkSize = Math.max(pageSize * 2, 50)
const seen = new Set()
const accepted = []
const inThreads = (ids) => cf.makeCondition([cf.makeCondition('emailMessageId', 'in', ids), cf.makeCondition('rootEmailMessageId', 'in', ids)], 'or')
// the threads of ids with a message in the view at or after the cursor, which were on an earlier page; with the
// index, those messages must match its free text too
const shownAtCursor = (ids) => {
    const rows = Array.from(makeFind(null).condition(inThreads(ids)).condition(cf.makeCondition('messageDate', 'greater-equals',
            new Date(beforeMillis))).selectField('emailMessageId').selectField('rootEmailMessageId').list())
    let matching = rows
    if (indexQuery != null && rows.length) {
        const matched = new Set()
        const messageIds = rows.map((row) => row.emailMessageId)
        for (let start = 0; start < messageIds.length; start += indexBatch) {
            const part = messageIds.slice(start, start + indexBatch)
            for (const id of indexIds([{field: {name: 'emailMessageId', op: 'in', values: part}}], part.length)) matched.add(id)
        }
        matching = rows.filter((row) => matched.has(row.emailMessageId))
