    return new Set(matching.map((row) => row.rootEmailMessageId || row.emailMessageId))
}
for (let window = nextWindow(); window != null && accepted.length <= pageSize; window = nextWindow()) {
    if (window.ids != null && !window.ids.length) continue
    let offset = 0
    while (accepted.length <= pageSize) {
        const rows = Array.from(withCursor(makeFind(window.ids)).selectField('emailMessageId').selectField('rootEmailMessageId')
                .selectField('messageDate').orderBy('-messageDate').orderBy('-emailMessageId').offset(offset).limit(chunkSize).list())
        offset += rows.length
        const fresh = []
        for (const row of rows) {
            const threadId = row.rootEmailMessageId || row.emailMessageId
            if (seen.has(threadId)) continue
            seen.add(threadId)
            fresh.push({threadId: threadId, viewMessageId: row.emailMessageId, sortDate: toMillis(row.messageDate)})
        }
        if (fresh.length) {
            const ids = fresh.map((candidate) => candidate.threadId)
            // a thread with a message in the view at or after the cursor was on an earlier page
            const shownBefore = beforeMillis != null ? shownAtCursor(ids) : new Set()
            const candidates = fresh.filter((candidate) => !shownBefore.has(candidate.threadId))
            if (candidates.length) {
                let find = ec.entity.find(MESSAGE).condition('emailAccountId', 'in', accountIds).condition(inThreads(ids))
                        .condition(cf.makeCondition('messageDate', 'not-equals', null))
                if (anywhere) { /* every folder */ }
                else if (inTrashView) find = find.condition(cf.makeCondition('emailFolderId', 'in', trashJunk))
                else if (trashJunk.length) find = find.condition(notTrashJunk())
                for (const field of LIST_FIELDS) find = find.selectField(field)
