                for (const row of find.orderBy('messageDate').orderBy('emailMessageId').list()) {
                    (byThread[row.rootEmailMessageId || row.emailMessageId] ||= []).push(plain(row))
                }
                const labelMap = labelsOf(Object.values(byThread).flat().map((row) => row.emailMessageId))
                for (const candidate of candidates) {
                    const messages = byThread[candidate.threadId]
                    if (!messages || !messages.length) continue
