    if ((operator === 'greater' || operator === 'less') && field !== 'size') { ec.message.addError(`The operator ${operator} is for the size only`); return }
    let value = given.value == null ? '' : String(given.value)
    if (field === 'hasAttachment') {
        value = ['false', 'n', 'no', '0'].includes(value.trim().toLowerCase()) ? 'N' : 'Y'
    } else if (field === 'size') {
        if (!/^\s*\d+(\.\d+)?\s*[kKmM]?[bB]?\s*$/.test(value)) { ec.message.addError(`${value} is not a size`); return }
    } else if (!value.trim()) {
