    switch (condition.field) {
        case 'from': values = [message.fromAddress, message.fromName, message.fromName ? `${message.fromName} <${message.fromAddress}>` : null]; break
        case 'to': values = addressesOf(message.toAddresses); break
        case 'cc': values = addressesOf(message.ccAddresses); break
