const identities = Array.from(ec.entity.find('moqui.basic.email.EmailIdentity').condition('emailAccountId', emailAccountId)
        .orderBy('emailIdentityId').list())
const identity = identities.find((candidate) => candidate.isDefault === 'Y') || identities[0] || null
const own = new Set([lower(account.emailAddress)].concat(identities.map((row) => lower(row.emailAddress))).filter((address) => address))
const headerValue = (headers, name) => {
    let found = null
    for (const line of String(headers || '').split(/\r?\n/)) {
        if (found != null) { if (/^[ \t]/.test(line)) { found += ' ' + line.trim(); continue } break }
        const colon = line.indexOf(':')
        if (colon > 0 && line.substring(0, colon).trim().toLowerCase() === String(name).toLowerCase()) found = line.substring(colon + 1).trim()
    }
    return found
}
const addressesIn = (list) => {
    const out = []
    for (const entry of String(list || '').split(',')) {
        const angle = /<([^>]+)>/.exec(entry)
        const address = lower(angle ? angle[1] : entry)
        if (address) out.push(address)
    }
    return out
}
// why a message gets no automatic reply, or null when it gets one
const SYSTEM_SENDER = /^(mailer-daemon|postmaster|no[-_.]?reply|do[-_.]?not[-_.]?reply|bounces?|listserv|majordomo)([+@-]|$)/i
const refusal = (message) => {
    const headers = message.headersString
    const sender = lower(message.fromAddress)
    if (!sender || !sender.includes('@')) return 'no sender'
    if (own.has(sender)) return 'mail from the account itself'
    if (SYSTEM_SENDER.test(sender)) return 'a no-reply or system sender'
    for (const name of ['List-Id', 'List-Unsubscribe', 'List-Post', 'X-Autoreply', 'X-Autorespond']) {
        if (headerValue(headers, name) != null) return `the mail has ${name}`
    }
    const precedence = lower(headerValue(headers, 'Precedence'))
    if (['bulk', 'list', 'junk', 'auto_reply'].includes(precedence)) return `the mail has Precedence: ${precedence}`
    const submitted = lower(headerValue(headers, 'Auto-Submitted'))
    if (submitted && submitted !== 'no') return `the mail has Auto-Submitted: ${submitted}`
    if (headerValue(headers, 'X-Auto-Response-Suppress') != null) return 'the mail has X-Auto-Response-Suppress'
    const returnPath = headerValue(headers, 'Return-Path')
    if (returnPath != null && /^<\s*>$/.test(returnPath.trim())) return 'a bounce (empty Return-Path)'
    const recipients = addressesIn(message.toAddresses).concat(addressesIn(message.ccAddresses))
    if (!recipients.some((address) => own.has(address))) return 'not sent to the account (Bcc or a list)'
    const received = toMillis(message.receivedDate) ?? toMillis(message.messageDate)
    if (received == null || received < sinceMillis) return 'received before the automatic reply was on'
    return null
}
// internal: a user's address, or one at the domain of a hosted or shared account or of the reply's own list
let internalDomains = null
const internalOf = {}
const isInternal = (address) => {
    if (internalOf[address] != null) return internalOf[address]
    if (internalDomains == null) {
        internalDomains = new Set()
        for (const row of ec.entity.find('moqui.basic.email.EmailAccount').condition('accountKindEnumId', 'in', ['EakHosted', 'EakShared'])
                .selectField('emailAddress').list()) {
            const at = lower(row.emailAddress).lastIndexOf('@')
            if (at > 0) internalDomains.add(lower(row.emailAddress).substring(at + 1))
        }
        for (const domain of String(reply.internalDomains || '').split(',')) if (lower(domain)) internalDomains.add(lower(domain))
    }
    const at = address.lastIndexOf('@')
    internalOf[address] = (at > 0 && internalDomains.has(address.substring(at + 1))) ||
            ec.entity.find('moqui.security.UserAccount').condition(cf.makeCondition('emailAddress', 'equals', address, false, true)).count() > 0
    return internalOf[address]
}
const textOf = (html) => html ? String(html).replace(/<(style|script)[^>]*>[\s\S]*?<\/\1>/gi, ' ').replace(/<br\s*\/?>/gi, '\n')
        .replace(/<\/(p|div|li|h[1-6])>/gi, '\n').replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
        .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim() : ''

const replied = new Set()
const messages = Array.from(ec.entity.find(MESSAGE).condition('emailMessageId', 'in', ids).condition('emailAccountId', emailAccountId)
        .orderBy('messageDate').list())
const folderKinds = {}
for (const folder of ec.entity.find('moqui.basic.email.EmailFolder').condition('emailAccountId', emailAccountId).list())
    folderKinds[folder.emailFolderId] = folder.folderKindEnumId
// the audience: everyone, internal senders and the owner's contacts, or internal senders only
const audience = reply.replyAudienceEnumId || 'EraEveryone'
let contacts = null
if (audience === 'EraContacts' && account.ownerUserId) {
    const external = Array.from(new Set(messages.map((message) => lower(message.fromAddress))
            .filter((address) => address.includes('@') && !isInternal(address))))
    if (external.length) {
        ec.message.pushErrors()
        const found = ec.service.sync().name('org.moqui.impl.EmailClientServices.filter#ContactAddresses')
                .parameters({userId: account.ownerUserId, emailAddressList: external}).disableAuthz().call()
        if (ec.message.hasError()) {
            ec.logger.log('error', `The contacts of the automatic reply of email account ${emailAccountId} could not be read, so it goes to no outside sender: ${ec.message.errorsString}`)
            contacts = new Set()
        } else if (found?.contactAddressList != null) {
            contacts = new Set(Array.from(found.contactAddressList).map(lower))
        }
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
const outsideAudience = (sender) => {
    if (audience === 'EraEveryone' || isInternal(sender)) return null
    if (audience === 'EraInternal') return 'not an internal sender (the reply is for internal senders only)'
    if (audience === 'EraContacts' && contacts != null && !contacts.has(sender)) return 'not one of the account owner\'s contacts'
    return null
}
for (const message of messages) {
    if (message.statusId !== 'ES_RECEIVED' || ['EfkJunk', 'EfkTrash'].includes(folderKinds[message.emailFolderId])) { skippedCount++; continue }
    const sender = lower(message.fromAddress)
    const why = refusal(message) ?? outsideAudience(sender)
    if (why != null || replied.has(sender)) {
        if (why) ec.logger.info(`No automatic reply of email account ${emailAccountId} to message ${message.emailMessageId}: ${why}`)
        skippedCount++
        continue
    }
    const last = ec.entity.find('moqui.basic.email.EmailOutOfOfficeSent').condition('emailAccountId', emailAccountId)
            .condition('toAddress', sender).one()
    if (last != null && toMillis(last.lastSentDate) > nowMillis - onceDays * DAY) { skippedCount++; continue }
    ec.message.pushErrors()
    try {
        const html = isInternal(sender) && reply.internalBodyHtml ? reply.internalBodyHtml : reply.bodyHtml
        const references = [].concat(String(message.referencesHeader || '').split(/\s+/), message.messageId ? [message.messageId] : [])
                .filter((id) => id)
        const answer = ec.entity.makeValue(MESSAGE)
        answer.setSequencedIdPrimary()
        answer.setFields({statusId: 'ES_DRAFT', emailAccountId: emailAccountId, emailServerId: account.emailServerId,
            emailIdentityId: identity ? identity.emailIdentityId : null,
            fromAddress: identity?.emailAddress || account.emailAddress, fromName: identity ? (identity.displayName ?? null) : (account.accountName ?? null),
            toAddresses: message.fromAddress, subject: reply.subject || `Automatic reply: ${message.subject || ''}`.trim(),
            contentType: 'text/html', body: html, bodyText: textOf(html), snippet: textOf(html).substring(0, 137), isRead: 'Y',
            messageDate: ec.user.nowTimestamp, inReplyTo: message.messageId ?? null,
            referencesHeader: references.length ? references.slice(-20).join(' ') : null, hasAttachment: 'N',
            headersString: 'Auto-Submitted: auto-replied\nX-Auto-Response-Suppress: All'}, true, null, null)
        answer.create()
        const sent = ec.service.sync().name('org.moqui.impl.EmailClientServices.deliver#DraftMessage')
                .parameters({emailMessageId: answer.emailMessageId, fromStatusIdList: ['ES_DRAFT']}).call()
        if (!ec.message.hasError()) {
            if (!sent.sent) ec.logger.warn(`The automatic reply of email account ${emailAccountId} to ${sender} waits in the Outbox: ${sent.sendError}`)
            const log = ec.entity.makeValue('moqui.basic.email.EmailOutOfOfficeSent')
            log.setFields({emailAccountId: emailAccountId, toAddress: sender, lastSentDate: ec.user.nowTimestamp,
                emailMessageId: message.emailMessageId}, false, null, null)
            log.createOrUpdate()
            replied.add(sender)
            sentCount++
        }
    } catch (err) {
        ec.message.addError(String(err.message || err))
    }
    if (ec.message.hasError()) ec.logger.log('error', `The automatic reply of email account ${emailAccountId} to message ${message.emailMessageId} failed: ${ec.message.errorsString}`)
    ec.message.clearErrors()
    ec.message.popErrors()
}

if (!ec.user.userId) { ec.message.addError('No user for the text block'); return }
if (userGroupId && ec.entity.find('moqui.security.UserGroupMember').condition('userId', ec.user.userId).condition('userGroupId', userGroupId)
        .conditionDate('fromDate', 'thruDate', null).disableAuthz().count() === 0) {
    ec.message.addError(`You are not in user group ${userGroupId}`); return }
const row = ec.entity.makeValue('moqui.basic.email.EmailTextBlock')
row.setSequencedIdPrimary()
row.setFields({ownerUserId: ec.user.userId, title: title, shortcut: shortcut, bodyHtml: bodyHtml, userGroupId: userGroupId || null},
        false, null, null)
row.create()
emailTextBlockId = row.emailTextBlockId

const row = ec.entity.find('moqui.basic.email.EmailTextBlock').condition('emailTextBlockId', emailTextBlockId).one()
if (row == null || row.ownerUserId !== ec.user.userId) { ec.message.addError(`Text block ${emailTextBlockId} not found`); return }
if (userGroupId && userGroupId !== row.userGroupId && ec.entity.find('moqui.security.UserGroupMember').condition('userId', ec.user.userId)
        .condition('userGroupId', userGroupId).conditionDate('fromDate', 'thruDate', null).disableAuthz().count() === 0) {
    ec.message.addError(`You are not in user group ${userGroupId}`); return }
if (title != null) {
    if (!title) { ec.message.addError('A text block needs a title'); return }
    row.set('title', title)
}
if (shortcut != null) row.set('shortcut', shortcut || null)
if (bodyHtml != null) row.set('bodyHtml', bodyHtml || null)
if (userGroupId != null) row.set('userGroupId', userGroupId || null)
row.update()

const row = ec.entity.find('moqui.basic.email.EmailTextBlock').condition('emailTextBlockId', emailTextBlockId).one()
if (row == null || row.ownerUserId !== ec.user.userId) { ec.message.addError(`Text block ${emailTextBlockId} not found`); return }
row.delete()

const row = ec.entity.find('moqui.basic.email.EmailSearch').condition('emailSearchId', emailSearchId).one()
if (row == null || row.ownerUserId !== ec.user.userId) { ec.message.addError(`Saved search ${emailSearchId} not found`); return }
row.delete()
